<?php
namespace ZCCNG;if(!defined('ABSPATH'))exit;
final class Audit{public static function log($event,$summary='',$context=[]){global $wpdb;$t=$wpdb->prefix.'zccng_audit_log';$wpdb->insert($t,['user_id'=>get_current_user_id(),'event_type'=>sanitize_key($event),'summary'=>sanitize_text_field($summary),'context'=>wp_json_encode(is_array($context)?$context:[]),'ip_hash'=>self::ip_hash(),'created_at'=>current_time('mysql',true)],['%d','%s','%s','%s','%s','%s']);}private static function ip_hash(){$ip=$_SERVER['REMOTE_ADDR']??'';return $ip?hash_hmac('sha256',$ip,wp_salt('auth')):'';}public static function recent($limit=12){global $wpdb;$t=$wpdb->prefix.'zccng_audit_log';$limit=max(1,min(50,(int)$limit));return (array)$wpdb->get_results("SELECT user_id,event_type,summary,created_at FROM $t ORDER BY id DESC LIMIT $limit",ARRAY_A);}}
